use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = serde_json::Value::from("false");
    let mut current = String::from(input.to_string());

    while let Some(token) = current.chars().next() {
        if token.is_whitespace() || token.is_alphabetic() {
            current.push(token);
        } else {
            let mut next = String::from(current);
            next.push(token);
            result = serde_json::Value::from(next);
            current = next;
        }
    }

    result
}
